<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Private Harmonies — Tailored Sessions</title>
<style>
:root{--bg:#07110f;--accent:#b1d9c9;--muted:#98a79f;--card:#0b1513;--radius:12px;--maxw:980px}
*{box-sizing:border-box}
body{margin:0;font-family:system-ui,Segoe UI,Helvetica,Arial;background:var(--bg);color:#e9fbf3;background-image:url('assets/img/pattern.svg');background-size:200px}
