.small{color:var(--muted);font-size:0.9rem}
.reveal{opacity:0;transform:translateY(12px);transition:opacity 480ms ease,transform 480ms cubic-bezier(.2,.9,.2,1)}
.reveal.visible{opacity:1;transform:none}
.disclaimer{margin-top:12px;color:#cfeee0;font-size:0.85rem}
.modal-backdrop{position:fixed;inset:0;background:rgba(1,3,2,0.6);display:none;align-items:center;justify-content:center;padding:20px}
.modal{background:#071312;padding:18px;border-radius:10px;max-width:520px;width:100%}
