<body>
<div class="container">
<header class="header">
<div class="brand"><span style="background:rgba(177,217,201,0.12);padding:6px 10px;border-radius:8px;color:var(--accent)">{{BUSINESS_NAME}}</span><div class="small">Private harmonies & tailored sessions</div></div>
<nav class="nav" aria-label="Main">
<a href="index.html">Home</a>
<a href="events.html">Gatherings</a>
<a href="private-sessions.html" class="primary">Private Harmonies</a>
<a href="pricing.html">Investments</a>
<a href="about.html">About</a>
</nav>
</header>

<section class="hero reveal" aria-labelledby="ps-title">
<div>
<h1 id="ps-title">Private harmonies crafted for your needs</h1>
<p>One-on-one sessions focus on intentional listening, breath alignment, and practical transitions out of rest.</p>
</div>
<div>
<a href="book.html" class="primary-btn">Request a private</a>
</div>
</section>

<section class="pillars" aria-label="Session pillars">
<div class="pillar reveal">
<h3>Solo Tuning</h3>
<p class="small">60 minutes: assessment, tailored sound sequence, notes & takeaways to carry forward.</p>
</div>
<div class="pillar reveal">
<h3>Duo Resonance</h3>
<p class="small">Shared sessions for partners or two friends. Focused attention for co-regulation & shared intention.</p>
</div>
<div class="pillar reveal">
<h3>Group Immersion</h3>
<p class="small">Small groups up to 8 for immersive practice and guided journaling. Ideal for teams and circles.</p>
</div>
</section>

<section class="case reveal">
<h3>What to expect</h3>
<p class="small">Sessions begin with a short intake, move into a 30–50 minute sound sequence, then close with a practical check-in. You leave with one clear, named next-step.</p>
</section>

<section class="case reveal">
<h3>Booking & planning</h3>
<p class="small">We schedule private sessions by request—choose a focus, and we'll suggest a structure. Travel for on-site group immersions is available; inquire at {{EMAIL}}.</p>
</section>

<section class="cta reveal">
<div>
<div><strong>Not sure if private is right?</strong></div>
<div class="small">Try a short guided practice below to get a sense of the pacing and tone.</div>
</div>
<div>
<button id="tryBtn" class="primary-btn">Try a mini practice</button>
</div>
</section>

<div class="disclaimer">
<strong>Contraindications:</strong> Private sound work is not a substitute for clinical care. Please consult medical guidance if pregnant, living with seizures, or managing serious cardiac conditions. If you have concerns, reach out to {{EMAIL}} before booking.
</div>

<footer style="margin-top:20px;color:var(--muted)">
<div>{{BUSINESS_NAME}} • {{CITY}}, {{STATE}} • <a href="contact.html" style="color:var(--muted);text-decoration:none">Contact</a></div>
</footer>
</div>

<div class="modal-backdrop" id="modalBackdrop" role="dialog" aria-modal="true" aria-hidden="true">
<div class="modal" role="document">
<header style="display:flex;justify-content:space-between;align-items:center">
<h2 style="margin:0">Try a focus exercise</h2>
<button id="closeModal" style="background:transparent;border:1px solid rgba(255,255,255,0.04);color:var(--muted);padding:6px 8px;border-radius:8px">Close</button>
</header>
<main style="margin-top:10px">
<p class="small">A brief practice to sample the private session pace.</p>
<div style="display:flex;gap:8px;margin-top:8px">
<button id="startBreathe" class="primary-btn">Breathe</button>
<button id="startJournal" style="padding:8px 10px;border-radius:8px;border:1px solid rgba(255,255,255,0.04);background:transparent;color:var(--muted)">Journal</button>
</div>
<section id="exerciseArea" style="margin-top:12px"></section>
</main>
</div>
</div>

<script>
(function(){
  const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const reveals = document.querySelectorAll('.reveal');
  if(prefersReduced){ reveals.forEach(e=>e.classList.add('visible')); return; }
  const io = new IntersectionObserver((entries)=>{ entries.forEach(en=>{ if(en.isIntersecting){ en.target.classList.add('visible'); io.unobserve(en.target); } }); },{threshold:0.14});
  reveals.forEach(el=>io.observe(el));
})();

const tryBtn = document.getElementById('tryBtn');
const modal = document.getElementById('modalBackdrop');
const closeBtn = document.getElementById('closeModal');
const exerciseArea = document.getElementById('exerciseArea');
tryBtn.addEventListener('click', ()=>{ modal.style.display='flex'; modal.setAttribute('aria-hidden','false'); startBreathe(); });
closeBtn.addEventListener('click', ()=>{ modal.style.display='none'; modal.setAttribute('aria-hidden','true'); exerciseArea.innerHTML=''; });

document.getElementById('startBreathe').addEventListener('click', startBreathe);
document.getElementById('startJournal').addEventListener('click', startJournal);

function startBreathe(){ exerciseArea.innerHTML = '<div style="text-align:center"><div class="timer" id="bT">4</div><p class="small">Slow inhale — hold — exhale. Repeat twice.</p></div>'; let n=4; const el=document.getElementById('bT'); const t=setInterval(()=>{ n--; if(n<=0){ clearInterval(t); el.textContent="Done"; setTimeout(()=>el.textContent='4',900);} else el.textContent=n; },1100); }

function startJournal(){ exerciseArea.innerHTML = '<div><textarea class="journal" placeholder="One line: my small next-step..."></textarea><div style="margin-top:8px"><button id="saveNote" class="primary-btn">Save</button></div></div>'; document.getElementById('saveNote').addEventListener('click',()=>{ const val=document.querySelector('.journal').value; const blob=new Blob([val],{type:'text/plain'}); const u=URL.createObjectURL(blob); const a=document.createElement('a'); a.href=u; a.download='intent.txt'; a.click(); URL.revokeObjectURL(u); modal.style.display='none'; }); }
</script>
</body>
</html>"} 
