<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Investments & Plans</title>
<style>
:root{--bg:#08120f;--panel:#0b1511;--accent:#9fd2bf;--muted:#98a79f;--radius:12px;--maxw:980px}
*{box-sizing:border-box}
body{margin:0;font-family:system-ui,Segoe UI,Helvetica,Arial;background:var(--bg);color:#ecfbf2;background-image:url('assets/img/pattern.svg');background-size:210px}
