.hero h1{margin:0;font-size:1.3rem}
.plans{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin-top:16px}
.plan{background:var(--panel);padding:14px;border-radius:10px;border:1px solid rgba(255,255,255,0.03)}
.plan h3{margin:0}
.price{font-weight:800;color:var(--accent);margin-top:8px}
.fine{font-size:0.85rem;color:var(--muted)}
.reveal{opacity:0;transform:translateY(14px);transition:opacity 500ms ease,transform 500ms cubic-bezier(.2,.9,.2,1)}
.reveal.visible{opacity:1;transform:none}
.cta{margin-top:18px;display:flex;justify-content:space-between;align-items:center}
.primary-btn{background:var(--accent);color:#05221a;padding:10px 14px;border-radius:10px;border:none}
.disclaimer{margin-top:12px;color:#caefe0;font-size:0.85rem}
</style>
</head>
<body>
<div class="container">
<header class="header">
<div><strong style="background:rgba(159,210,191,0.12);padding:6px 8px;border-radius:8px;color:var(--accent)">{{BUSINESS_NAME}}</strong><div class="small">Thoughtful pricing for focused rest</div></div>
<nav class="nav" aria-label="Main">
<a href="index.html">Home</a>
<a href="events.html">Gatherings</a>
<a href="private-sessions.html">Private Harmonies</a>
<a href="pricing.html" class="primary">Investments</a>
<a href="book.html">Book</a>
</nav>
</header>

<section class="hero reveal">
<div>
<h1>Flexible support—single sessions, packs, and ongoing plans</h1>
